import heapq

def match(orders):
    buy_heap = []   # max-heap by price: stored as (-price, seq, oid)
    sell_heap = []  # min-heap by price: stored as (price, seq, oid)
    book = {}       # id -> {'side','price','qty','seq'}
    seq_counter = 0
    trades = []

    def add_to_book(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def pop_valid_top(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            if oid in book and book[oid]['qty'] > 0:
                return item
            else:
                heapq.heappop(heap)
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        seq = seq_counter
        seq_counter += 1

        remaining = qty
        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            top = pop_valid_top(opp_heap)
            if top is None:
                break
            opp_oid = top[2]
            opp = book[opp_oid]
            opp_price = opp['price']

            if typ != 'market':
                if side == 'buy' and opp_price > price:
                    break
                if side == 'sell' and opp_price < price:
                    break

            trade_qty = min(remaining, opp['qty'])
            if side == 'buy':
                trades.append([oid, opp_oid, opp_price, trade_qty])
            else:
                trades.append([opp_oid, oid, opp_price, trade_qty])

            remaining -= trade_qty
            opp['qty'] -= trade_qty

            if opp['qty'] == 0:
                heapq.heappop(opp_heap)
                del book[opp_oid]

        if typ == 'limit' and remaining > 0:
            add_to_book(oid, side, price, remaining, seq)
        # ioc and market discard any remainder

    return trades

